  but does not match 'return v > 0'

Given:
-(void) foo {
  int x = 1;
  dispatch_sync(queue, ^{ int y = 2; });
}
declStmt(forCallable(objcMethodDecl()))
  matches 'int x = 1'
  but does not match 'int y = 2'.
whereas declStmt(forCallable(blockDecl()))
  matches 'int y = 2'
  but does not match 'int x = 1'.

